package edu.gcu.cst339.lab2_chinook_api.artist;

/**
 * Data transfer object used as the JSON request and response body for artists.
 *
 * @param artistId the artist ID; generated by the database, so it is ignored on
 *                 create and taken from the URL on update
 * @param name     the artist name (at most 120 characters)
 */
record ArtistDto(
    Integer artistId,
    String name
) {
    /**
     * Converts an artist entity into a DTO.
     *
     * @param artist the entity to convert
     * @return a DTO containing the entity's ID and name
     */
    static ArtistDto fromEntity(Artist artist) {
        return new ArtistDto(
            artist.getArtistId(), 
            artist.getArtistName()
        );
    }
} 